import { describe, it, expect } from 'vitest';
import { createEngine } from '../../js/sim/engine.js';

// CHECKS: finding 1-06's contract — the top-level primary* keys name the
// pool's primary backend (10.11 at stage 2) while the per-server shapes on
// snapshot.servers[i] stay authoritative, and a 10.12-side fs edit lands
// ONLY in servers[1].files (the named counter-example); at stage 1 the one
// backend IS the primary, so setWebFile('10.1', ...) rides primaryFiles.
describe('the primary shape names itself', () => {
  it("the primary shape names itself — 'primaryQueue' / 'primaryFiles' - the pool's primary-backend story, not an aggregate", () => {
    const engine = createEngine({ seed: 42, stage: 2 });
    engine.setWebFile('10.12', '/about', 'New body');
    const snap = engine.snapshot();
    expect(snap.primaryQueue).toEqual(snap.servers[0].queue);
    expect(snap.primaryFiles['/about']).toBe('This is the about page');
    expect(snap.servers[0].files['/about']).toBe('This is the about page');
    expect(snap.servers[1].files['/about']).toBe('New body');

    const stage1 = createEngine({ seed: 42, stage: 1 });
    stage1.setWebFile('10.1', '/about', 'Stage-1 body');
    const single = stage1.snapshot();
    expect(single.primaryFiles['/about']).toBe('Stage-1 body');
    expect(single.primaryQueue).toEqual(single.servers[0].queue);
  });
});
